<?php

declare(strict_types=1);

namespace Municipio\Controller\School;

/**
 * Class MediaItemsCounter
 */
class MediaItemsCounter
{
    /**
     * Count the number of image and video items generated by MediaItemsGenerator
     *
     * @param mixed $mediaItems
     * @return int
     */
    public static function count(mixed $mediaItems): int
    {
        if (!is_array($mediaItems)) {
            return 0;
        }

        return count($mediaItems['imageItems'] ?? []) + count($mediaItems['videoItems'] ?? []);
    }
}
